class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        metrics, definitions = {}, {}
        saved = capture_diagnostic_state(self.view.model)
        try:
            self.view.model.eval()
            run_existing_probes_independently(metrics, definitions, train_loader)
            parity = verify_current_checkpoint_and_exported_serving(self.view)
            metrics['serving_parity'] = parity
            if not parity.passed:
                metrics['candidate_audit'] = unavailable(parity.reason)
            else:
                frequencies = count_public_training_interactions(self.view.user_train)
                lexical_index = fit_local_tfidf(public_titles_and_descriptions())
                endpoints = select_fixed_eligible_training_endpoints(seed=42, limit=32)
                for endpoint in endpoints:
                    if audit_cap_reached():
                        record_partial_completion()
                        break
                    prefix, target = endpoint.prefix, endpoint.target
                    x = left_pad(prefix[-(maxlen-1):] + [MASK], maxlen)
                    for draw in range(3):
                        for regime in ['uniform', 'frequency_matched', 'lexical']:
                            negatives = construct_99_unique_eligible_items(
                                regime, target, complete_prefix=prefix,
                                frequencies=frequencies, lexical_index=lexical_index,
                                dedicated_seed=declared_seed(endpoint, draw, regime))
                            if negatives.unavailable:
                                record_unavailable(regime, negatives.reason)
                                continue
                            features = self.view.log2feats(x)
                            final_index = maximum_nonpadding_index(x)
                            scores = self.view.predict_score(
                                features, [target] + negatives)
                            record_rank_margin_hit(scores, final_index, target)
                metrics['candidate_audit'] = summarize_paired_user_clustered_results()
            return {'metrics': metrics, 'metric_definitions': definitions}
        finally:
            restore_diagnostic_state(self.view.model, saved)


def diagnosis_interpreter_prompt(raw_diagnosis):
    return render_measured_metrics_definitions_counts_and_availability(
        raw_diagnosis,
        instruction='Distinguish descriptive candidate sensitivity from host validation; '
                    'do not infer dislike, compatibility, mood, or improvement.')

